<?php
require __DIR__.'/../vendor/autoload.php';$app=require __DIR__.'/../bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
use Illuminate\Support\Facades\Http;
$text=str_repeat('The fictional owner says the pet is eating normally. ',15);
$schema=['type'=>'object','properties'=>['segments'=>['type'=>'array','items'=>['type'=>'object','properties'=>['segment_id'=>['type'=>'integer'],'quotes'=>['type'=>'array','items'=>['type'=>'object','properties'=>['text'=>['type'=>'string'],'category'=>['type'=>'string']],'required'=>['text','category']]]],'required'=>['segment_id','quotes']]]],'required'=>['segments']];
try{$r=Http::withToken(config('ai.groq_api_key'))->acceptJson()->asJson()->timeout(20)->post('https://api.groq.com/openai/v1/chat/completions',['model'=>config('ai.groq_model'),'temperature'=>0.2,'max_completion_tokens'=>2048,'messages'=>[['role'=>'system','content'=>'Extract exact quotes from the fictional source.'],['role'=>'user','content'=>$text]],'response_format'=>['type'=>'json_schema','json_schema'=>['name'=>'vetti_interpretation','strict'=>false,'schema'=>$schema]]]);$keys=['retry-after','x-ratelimit-limit-requests','x-ratelimit-remaining-requests','x-ratelimit-reset-requests','x-ratelimit-limit-tokens','x-ratelimit-remaining-tokens','x-ratelimit-reset-tokens'];$h=[];foreach($keys as $k){$v=$r->header($k);if(is_string($v)&&preg_match('/^[0-9a-zA-Z.,: +\-]+$/D',$v)&&strlen($v)<=100)$h[$k]=$v;}$msg=(string)$r->json('error.message');$kind=preg_match('/tokens per day|TPD/i',$msg)?'tokens_per_day':(preg_match('/tokens per minute|TPM/i',$msg)?'tokens_per_minute':(preg_match('/requests per day|RPD/i',$msg)?'requests_per_day':(preg_match('/requests per minute|RPM/i',$msg)?'requests_per_minute':'unspecified')));echo json_encode(['status'=>$r->status(),'limit_kind'=>$kind,'headers'=>$h]).PHP_EOL;}catch(Throwable $e){echo json_encode(['error'=>'request_failed']).PHP_EOL;}
